"Create ABC Score": "ABC 楽譜を作成",
"Generate song": "曲を生成",
"Nothing playing": "再生中のものはありません",
"Play this song now (the player keeps what it was playing until you do). Double-clicking a song in the list plays it too.": "この曲を今すぐ再生（そうするまでプレーヤーは再生中のものを続けます）。一覧の曲をダブルクリックしても再生されます。",
"▶ Play this song": "▶ この曲を再生",
"no run yet": "まだ実行なし",
"Back to the run": "実行に戻る",
"Queued": "待機中",
"Cancel run": "実行を取り消す",
"Replace this section…": "このセクションを差し替える…",
"Replace a section": "セクションの差し替え",
"Its words as the lyrics have them: change what you will, and it is sung anew from its start to its end; the rest of the take stays as it is.": "歌詞にあるとおりの言葉です。好きなように変えると、その始まりから終わりまでが歌い直されます。テイクの残りはそのままです。",
"Two versions": "2 バージョン",
"One version": "1 バージョン",
"Sing it anew": "歌い直す",
"More syllables than the section held: the model sings them faster, or runs over the cut": "セクションに収まっていたより音節が多い：モデルは速く歌うか、継ぎ目を越えます",
"Fewer syllables than the section held: the model may stretch them or leave a rest": "セクションに収まっていたより音節が少ない：モデルは引き伸ばすか、休符を残すかもしれません",
"Sung anew: its versions come as takes of their own, children of this one": "歌い直し中：バージョンはこのテイクの子として、別のテイクになります",
"Sung anew here (Replace a section); the rest is as its parent made it": "ここは歌い直し（セクション差し替え）。残りは親テイクのままです",
"anew": "差替",
"This section cannot be replaced: its lines were not heard clearly": "このセクションは差し替えられません：行がはっきり聞き取れませんでした",
"Epochs": "エポック",
"How many epochs: every track of the set once an epoch, one track a step; the run's steps are the set's tracks times this. A small set is learnt by heart fast: the green epochs in the Telemetry are the ones to hear first, often before the last.": "エポック数：1 エポックでセットの各トラックを 1 回ずつ、1 ステップに 1 トラック。実行のステップ数はセットのトラック数 × この値です。小さなセットはすぐに丸暗記されます。テレメトリの緑のエポックから先に聴いてください。最後のものより前のことがよくあります。",
"Cancel this run?": "この実行を取り消しますか？",
"What the engine has made of it so far is lost.": "エンジンがここまで作ったものは失われます。",
"Its queued versions go with it.": "キューにある同じ曲のバージョンも一緒に取り消されます。",
"Keep it running": "このまま続ける",
"Your next song starts here": "次の曲はここから始まります",
