"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten. Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "⚠ スタイルに書いた名前は依頼であって約束ではありません。▶ A と ▶ B が鳴らすのは YuE2 がそれに対して出す音で、10 回に 9 回ほどです。見事なプローブもあり A と B も一致しているのに、頼んだ楽器ではないこともあります：名前ではなく耳を信じてください。",
