"How wide the adapter's change is: 16 for one voice or instrument, 32 for a style, 64 for many voices, 128 at most.": "アダプターによる変化の幅：声や楽器 1 つなら 16、スタイルなら 32、多くの声なら 64、最大 128。",
"Whether the music half learns (the part that writes the song's tokens), and how hard its lesson pulls against the anchor: 0 leaves it as the base, a timbre only; raise it for diction and style. What counts is the anchor's share of it, not its size.": "音楽の半分（曲のトークンを書く部分）が学ぶかどうか、そしてその学習がアンカーに対してどれだけ強く引くか：0 ならベースのまま（音色のみ）。発音とスタイルには上げてください。大事なのはアンカーの割合で、大きさではありません。",
"Pulls the music half back toward the base model, so it keeps what the set does not show. Read it as a share of the AR weight: a tenth lets it move, as much as the weight holds it near the base. Nothing at AR weight 0.": "音楽の半分をベースモデルの方へ引き戻し、セットが示さないものを失わないようにします。AR の重みに対する割合として読んでください：10 分の 1 なら動けて、重みと同じならベースの近くに留めます。AR の重みが 0 なら何もしません。",
"The music half's learning rate as a share of the one above: the knob that makes it learn faster or slower (0.5: half as fast). It learns a small set by heart quickly.": "音楽の半分の学習率（上の値に対する割合）：学びの速さを変える設定です（0.5：半分の速さ）。小さなセットはすぐに丸暗記します。",
