"All together · loss": "全体 · 損失",
"Music half · ar_ce (AR)": "音楽側 · ar_ce（AR）",
"How well the sound half predicts the noise it has to take away. Lower is better. It jumps from step to step with the random noise level of each step: read the bold line, the running average.": "音響側が取り除くべきノイズをどれだけ予測できているか。低いほど良い。各ステップのランダムなノイズレベルでステップごとに跳ねます：太線の移動平均を読んでください。",
"How well the music half predicts the song’s own tokens. Lower is better; close to 0 it knows the songs by heart, and an earlier epoch is then the better adapter.": "音楽側が曲自身のトークンをどれだけ予測できているか。低いほど良い。0 に近いと曲を丸暗記しているので、前のエポックのほうが良いアダプターです。",
"(its average, dashed)": "（その平均、破線）",
"over the curve: the step, its epoch, the value there": "曲線上：ステップ、そのエポック、その位置の値",
"No run chosen: pick one in the column on the right, or start one in step 3.": "実行が選ばれていません：右の列で選ぶか、ステップ 3 で開始してください。",
