"what a probe gave instead of its instrument": "プローブが指定の楽器の代わりに出したもの",
"Nothing matches.": "一致するものはありません。",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ スタイルに書いた名前は要望であって約束ではありません。▶ A と ▶ B で鳴るのは YuE2 がそれに対して出すもので、10 回に 9 回ほどです。",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "見事なプローブもあり、A と B が一致していても、楽器が指定したものではないことがあります：名前ではなく耳を信じてください。",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "YuE2 に演奏させたもの。1 度に 1 つの楽器またはスタイルを、2 分のプローブ（最初のものは 1 分）で、それぞれ A と B の 2 つのシードで。",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "楽器は曲全体のスタイルを形作ります：1 つ名前を挙げると編曲も動きます。擦り切れたレコードのようなパチパチ音や紙のこすれる音は運の悪いシードです：別のシードで作り直してください。",
