"💎 From Hugging Face…": "💎 Hugging Face から…",
"💎 Sets from Hugging Face": "💎 Hugging Face のセット",
"The studio's approved sets, as their author published them. Each comes in as a workspace of its own, locked against deletion: its takes as MP3 with their covers, titles and notes. Only what you ask for is downloaded.": "作者が公開したままの、スタジオ承認セット。それぞれ削除できないようロックされた独自のワークスペースとして入ります：テイクはカバー、タイトル、メモ付きの MP3。頼んだものだけがダウンロードされます。",
"Asking Hugging Face…": "Hugging Face に問い合わせ中…",
"published {0}": "公開 {0}",
"{#0} takes here": "ここに {#0} テイク",
"Not here yet": "まだここにありません",
"Getting…": "取得中…",
"Try again": "再試行",
