"Full screen": "全画面",
"Width of the form and the take": "フォームとテイクの幅",
"Drag: the form takes 55 to 70 % of the width; below 55 the takes take 60 % and the form one column · double-click: the default": "ドラッグ：フォームが幅の 55〜70 %。55 未満ではテイクが 60 %、フォームは 1 列 · ダブルクリック：既定",
"the transcriber": "採譜器",
"written from its sound by {0}": "{0} が音から書き起こし",
