"Tick what to look for. A take is shown when it has all of the ticked (AND), any of them (OR) or none of them (NOR); the numbers count the takes of this place.": "探すものにチェックを入れてください。チェックしたものをすべて持つ（AND）、どれか 1 つを持つ（OR）、どれも持たない（NOR）テイクが表示されます。数字はこの場所のテイク数です。",
