"A female voice: the register named among the female ones": "女性の声：女性の中での声域名",
"What the folder holds": "フォルダーの中身",
"Male or female": "男性か女性か",
"not measured yet": "まだ測定していません",
"Models and LoRAs": "モデルと LoRA",
"What the install brings": "インストールに含まれるもの",
"More models": "その他のモデル",
"Saved briefs": "保存したブリーフ",
"AITK": "AITK",
"Ruach": "Ruach",
