"Any model of openrouter.ai/models, written provider/model; the field offers the whole list as you type, each with its price per million tokens in and out. The quick picks fill it in.": "openrouter.ai/models の任意のモデルを プロバイダー/モデル の形で。入力中に一覧全体を、100 万トークンあたりの入出力の価格付きで提示します。クイック選択で入力されます。",
