"Export all: every document of the Writer, with its versions, the takes made from it and its trash, in one file (a backup)": "すべてエクスポート：ライターの全ドキュメントを、バージョン、そこから作ったテイク、ゴミ箱ごと 1 つのファイルに（バックアップ）",
