"Import a Writer backup: what is missing here comes in; the same is left alone; a document that differs from its namesake here comes in beside it as a copy. Nothing here is written over": "ライターのバックアップをインポート：ここにないものは追加、同じものはそのまま、ここの同名のものと異なるドキュメントはコピーとして横に追加します。ここにあるものは何も上書きしません",
"A Writer backup to import": "インポートするライターのバックアップ",
"The documents column: drag to widen; ← → from the keyboard; Home or a double click for its own width": "ドキュメント列：ドラッグで広げる。キーボードの ← →。Home かダブルクリックで元の幅",
