"A mark of the score. Each section of the lyrics with its words: the take's menu, Find the sections by ear": "楽譜の印。歌詞の各セクションとその言葉：テイクのメニューの「耳でセクションを探す」",
"Wait: Whisper is binding the lyrics to the wave; the words come here in a moment": "お待ちください：Whisper が歌詞を波形に結び付けています。言葉はまもなくここに表示されます",
