"it goes onto the clipboard and, where you say, into the Style prompt; a name the Style holds already is marked; a lyrics tag goes onto the clipboard only": "クリップボードに入り、指定した場所ではスタイルのプロンプトにも入ります。スタイルにすでにある名前には印が付きます。歌詞タグはクリップボードにだけ入ります",
