"Transcribed {0} in {1}. Check the melody under Supply your own score, then write the new lyrics and style.": "{0} を {1} で採譜しました。「自分の楽譜を指定」でメロディを確認し、新しい歌詞とスタイルを書いてください。",
"1 take carries a score you can remix.": "リミックスできる楽譜を持つテイクが 1 件あります。",
"{#0} takes carry a score you can remix.": "リミックスできる楽譜を持つテイクが {#0} 件あります。",
"Make a song in Full plan or Melody only mode first; Direct mode keeps no score.": "まずフルプランかメロディのみのモードで曲を作ってください。ダイレクトモードは楽譜を残しません。",
