"Its trigger words into the prompt": "トリガーワードをプロンプトへ",
"Copy its trigger words": "トリガーワードをコピー",
"Trigger words go into the prompt by themselves": "トリガーワードは自動でプロンプトに入ります",
"Look it up on Civitai": "Civitai で調べる",
