"To the art's trash…": "アートのゴミ箱へ…",
"What it is made for, its trigger words, its file and what its trainer wrote into it": "何のために作られたか、トリガーワード、ファイル、学習者が書き込んだ内容",
"When an adapter comes into the run its trigger words are added to the prompt, and taken out when it leaves": "アダプターが実行に入るとトリガーワードがプロンプトに加わり、外れると取り除かれます",
"Its SHA-256 alone goes to civitai.com: its name, base model and trigger words come back": "civitai.com に送るのは SHA-256 だけ：名前、ベースモデル、トリガーワードが返ってきます",
"With the files beside it; the Librarian's Trash (Art) gives it back": "横にあるファイルごと。司書の「ゴミ箱（アート）」から戻せます",
"Known to Civitai: {0}": "Civitai で既知：{0}",
