"Passes": "パス",
"Each pass runs its model over the picture as it stands and lands at the picture's own size × its factor (each factor the picture's, not the pass before's): Viktor's ComfyUI stack, CR Apply Multi Upscale. Then the long side, then the colours put back to the picture's.": "各パスは現在の画像にモデルをかけ、元画像のサイズ × 係数に到達します（係数はいつも元画像基準で、前のパス基準ではありません）：Viktor の ComfyUI スタック、CR Apply Multi Upscale。その後に長辺、最後に色を元画像に戻します。",
