"all protected: the protection comes off": "すべて保護済み：保護を外します",
"never to the trash, never deleted": "ゴミ箱に入れず、削除もしない",
"Every take is a favourite or protected; nothing to delete": "すべてのテイクがお気に入りか保護済みです。削除するものはありません",
