"a painter kept between runs · GPU {0}": "実行の間保持している画家 · GPU {0}",
"Unload model: {0} GB in the card’s memory now, and the Artist’s painter kept between runs on GPU {1}": "モデルをアンロード：今カードのメモリに {0} GB、さらに GPU {1} で実行の間保持している絵師の画家",
"Unload model: {0} GB in the card’s memory now (busy: it waits), and the Artist’s painter kept between runs on GPU {1}": "モデルをアンロード：今カードのメモリに {0} GB（使用中：待機します）、さらに GPU {1} で実行の間保持している絵師の画家",
"Unload: the Artist’s painter kept between runs on GPU {0}: let it go now": "アンロード：GPU {0} で実行の間保持している絵師の画家を今すぐ解放",
