"The Artist’s painters let go (GPU {0})": "絵師の画家たちを解放しました（GPU {0}）",
"The Artist paints on GPU {0}: Unload again when its run ends": "絵師は GPU {0} で描画中です：実行が終わったらもう一度アンロードしてください",
"“{0}” has this picture as its cover: take it off the take too, or leave it? The take keeps a copy of its own.": "「{0}」はこの画像をカバーにしています：テイクからも外しますか、それとも残しますか？ テイクは自分のコピーを持っています。",
"{#0} takes have these pictures as their covers: take the covers off them too, or leave them? Each take keeps a copy of its own.": "{#0} 件のテイクがこれらの画像をカバーにしています：そちらのカバーも外しますか、それとも残しますか？ 各テイクは自分のコピーを持っています。",
