"Spectrum over the wave": "波形の上にスペクトル",
"Spectrum over the wave: the pointer on the wave brings the whole take's spectrogram up over the player, as wide as the wave, the section's words above it. Click to turn it off.": "波形の上にスペクトル：波形にポインターを置くと、テイク全体のスペクトログラムが波形と同じ幅でプレーヤーの上に現れ、その上にセクションの歌詞が出ます。クリックでオフ。",
"The take's spectrum": "テイクのスペクトル",
"spectral centroid": "スペクトル重心",
"The spectral centroid: where the sound's weight sits at each moment, its brightness; higher is brighter": "スペクトル重心：各瞬間に音の重みがある位置、つまり明るさ。高いほど明るい",
"RMS: how loud each moment is, in dBFS, in the lane at the foot; the dashed line is the take's own average": "RMS：各瞬間の音量（dBFS）、下の帯に表示。破線はテイク自身の平均",
"Frequency scale": "周波数スケール",
"The frequencies on a log scale, as the ear hears them: each octave as tall as the next": "耳の聞こえ方に合わせた対数スケールの周波数：どのオクターブも同じ高さ",
"The frequencies on a linear scale: the highs wide, the lows packed at the foot": "線形スケールの周波数：高域は広く、低域は下に詰まります",
"The mean power of each band over the whole take (Welch, dB): SUB 20–80 Hz, LOW 80–300, MID 300–2k, HI-MID 2–6k, HIGH 6–12k, AIR 12–20k": "テイク全体での各帯域の平均パワー（Welch、dB）：SUB 20–80 Hz、LOW 80–300、MID 300–2k、HI-MID 2–6k、HIGH 6–12k、AIR 12–20k",
"peak {0} dBFS": "ピーク {0} dBFS",
"RMS {0} dBFS": "RMS {0} dBFS",
"centroid {0}": "重心 {0}",
"loudest {0}": "最大 {0}",
"here {0}": "ここ {0}",
"{0} Hz": "{0} Hz",
"no spectrum in this page": "このページにスペクトルはありません",
