"its painter said nothing for {#0} minutes: stopped": "画家が {#0} 分間何も出力しませんでした：停止",
"its painter said nothing for {#0} s: stopped": "画家が {#0} 秒間何も出力しませんでした：停止",
"A second pass, as Viktor's ComfyUI workflow makes it: the picture brought up 1.5 or 2 times and painted over by its own painter, adapters, prompt and seed, with the form's steps and sampler; a run of its own": "Viktor の ComfyUI ワークフローと同じ 2 回目のパス：絵を 1.5 倍または 2 倍にし、同じ画家、アダプター、プロンプト、シードで描き直します。ステップとサンプラーはフォームのもの。独立した実行です",
"Second pass…": "2 回目のパス…",
"How much the second pass may change the picture: 0.3 keeps its drawing and adds detail, 0.5 sharpens its matter, 0.7 repaints its forms": "2 回目のパスが絵をどれだけ変えてよいか：0.3 は描線を保って細部を足し、0.5 は質感を研ぎ、0.7 は形を描き直します",
"Second pass asked:": "2 回目のパスを依頼：",
"The second pass ×{0} waits for a card with room, then paints the picture over": "2 回目のパス ×{0} は空きのあるカードを待ってから絵を描き直します",
"No second pass: {0}": "2 回目のパスはできません：{0}",
"second pass ×{0}": "2 回目のパス ×{0}",
"Extra noise": "追加ノイズ",
"Fresh noise added to the picture before it is painted from, as Viktor's ComfyUI workflow does (InjectLatentNoise): 0 none, 0.3 new grain and detail, 0.6 his second pass, above 1 the picture's forms begin to break": "絵から描き始める前に新しいノイズを絵に加えます。Viktor の ComfyUI ワークフロー（InjectLatentNoise）と同じです：0 はなし、0.3 は新しい粒子と細部、0.6 は彼の 2 回目のパス、1 を超えると絵の形が崩れ始めます",
"extra noise {0}": "追加ノイズ {0}",
