"The computer's keys: A S D F G H J K L ; ' white, W E T Y U O P ] black · Z X an octave": "コンピューターのキー：A S D F G H J K L ; ' が白鍵、W E T Y U O P ] が黒鍵 · Z X でオクターブ",
