"The instruments did not load ({0}): the roll plays its own built voices until it is opened again": "楽器を読み込めませんでした（{0}）：もう一度開くまで、ロールは内蔵の音で鳴らします",
"The instruments are on their way…": "楽器を読み込み中…",
"MIDI needs the studio opened as localhost or over https; this page is {0}. From another computer: ssh -L {1} {2}, then {3}": "ブラウザーが MIDI を使わせるのは localhost か https のページだけです。このページは {0} です。別のコンピューターからは ssh -L {1} {2} のあと {3} を開いてください",
"{0} control port(s) left to the controls": "操作用ポートはコントロールに残しました：{0}",
