"A MIDI keyboard of this computer: its keys play here; with Rec on, a key writes a note at the cursor and the cursor steps on": "このコンピューターの MIDI キーボード：その鍵盤がここで鳴ります。Rec 中は鍵盤でカーソルに音を書き、カーソルが進みます",
"Rec: a key (of the MIDI keyboard, the computer's keys or the keys below) writes a note of the grid's length at the cursor into the staff in hand, and the cursor steps on": "Rec：鍵盤（MIDI キーボード、コンピューターのキー、下に描かれた鍵盤）で、手元の譜表のカーソル位置にグリッドの長さの音を書き、カーソルが進みます",
"Rec": "Rec",
"The roll into the score in the box: only the lines whose notes or chords changed are written anew, every other line stays as YuE2 wrote it": "ロールを入力欄の譜面へ：音かコードが変わった行だけを書き直し、ほかの行はすべて YuE2 が書いたまま",
"As YuE2 wrote it": "YuE2 が書いたまま",
"As it stands now": "今の状態",
"Click: a note · drag: move, its lower edge: longer · right-click or Delete: away · Shift and keys together: a chord on the cursor's bar · keys A S D F G H J K L ; ' and W E T Y U O P ]: a keyboard and a half, Z X an octave · ←→ a semitone, ↑↓ a step · Tab: the other staff · wheel: time, Ctrl+wheel: closer · F11: the whole screen": "クリック：音を置く · ドラッグ：移動、下端で長く · 右クリックか Delete：削除 · Shift とキーを同時に：カーソルの小節にコード · A S D F G H J K L ; ' と W E T Y U O P ]：1オクターブ半、Z X で1オクターブ · ←→ 半音、↑↓ 1ステップ · Tab：もう一方の譜表 · ホイール：時間、Ctrl+ホイール：拡大 · F11：全画面",
