"One's own MIDI keyboard: the keys it reaches marked over the keyboards (they keep their size); ‹ › move the keys in sight an octave": "自分の MIDI キーボード：届く鍵盤を上に印で示します（鍵盤の大きさは変わりません）。‹ › で見えている鍵盤を1オクターブ動かします",
"Hear the score as YuE2 wrote it": "YuE2 が書いたままの譜面を聴く",
