"Piano roll": "ピアノロール",
"The score in the box as a piano roll: both staves, Vocal and Ins, a note a click; written back into the score line by line, every untouched line as YuE2 wrote it": "入力欄の譜面をピアノロールで：Vocal と Ins の両方の譜表、クリックで1音。譜面へは行ごとに書き戻し、触れていない行は YuE2 が書いたまま",
"No score in the box yet: load one, plan one in Full, or import a MIDI file first": "入力欄に譜面がまだありません：読み込むか、Full で計画するか、MIDI を取り込んでください",
"The score does not read, so the roll cannot open it:": "譜面が読めないため、ロールで開けません：",
