"The vocal staff in hand: what is sung. Ins stays drawn faint behind it": "手元はボーカルの譜表：歌われるもの。Ins は後ろに薄く残ります",
"The instruments' staff in hand: their melody. Vocal stays drawn faint behind it": "手元は楽器の譜表：そのメロディ。Vocal は後ろに薄く残ります",
"Grid and the length of a new note": "グリッドと新しい音の長さ",
