"Both staves from the cursor, as plain tones at the score's tempo (Space); a click on the ruler sets the cursor": "カーソルから両方の譜表を、譜面のテンポで単純な音として（スペース）。ルーラーのクリックでカーソルを置きます",
"The roll into the score in the box: only the lines whose notes changed are written anew, every other line stays as YuE2 wrote it": "ロールを入力欄の譜面へ：音が変わった行だけを書き直し、ほかの行はすべて YuE2 が書いたまま",
"Write into the score": "譜面に書き込む",
"Close (Esc); what is not written into the score is dropped": "閉じる（Esc）。譜面に書き込んでいないものは消えます",
"Click: a note · drag: move or stretch · right-click or Delete: away · ↑↓ a semitone, Shift an octave · ←→ a step of the grid · Shift+click: pick more · Tab: the other staff": "クリック：音を置く · ドラッグ：移動・伸縮 · 右クリックか Delete：削除 · ↑↓ 半音、Shift で1オクターブ · ←→ グリッド1つ · Shift+クリック：追加で選択 · Tab：もう一方の譜表",
