"The chain: its profile, Run the chain and On the workspace…; it runs the way drawn thick": "チェーン：プロファイル、チェーンを実行、ワークスペースで…。太く描かれた道を実行します",
"A track from anywhere (WAV, FLAC, MP3…) into the library as a take, marked imported; a way wired from here runs on each one imported next": "どこからでもトラック（WAV、FLAC、MP3…）をテイクとしてライブラリへ、インポートの印付きで。ここから引いた道は次のインポートごとに自動で流れます",
"Every file made from this take, each under the one it came from: play, compare, rate, delete": "このテイクから作られたすべてのファイルを、元のファイルの下に：再生、比較、評価、削除",
"The spectrum of the take or of a file made from it: how loud each band is, over time": "テイクや、そこから作ったファイルのスペクトル：各帯域の時間ごとの大きさ",
"Faults measured in a file: clicks, clipping, the frame buzz, a hum": "ファイルで測った欠陥：クリック、クリップ、フレームのノイズ、ハム",
"The lyrics held against what is sung (Whisper): which lines came and which did not": "歌われた内容と歌詞の照合（Whisper）：どの行が歌われ、どの行が抜けたか",
"The frame buzz of YuE2's sound out of the take: needed for every YuE2 take, off for a track from elsewhere": "YuE2 の音のフレームノイズをテイクから除きます：YuE2 のテイクには毎回必要、外部のトラックではオフ",
"UniverSR redraws the top of the spectrum above a cutoff, the original kept below it": "UniverSR がカットより上のスペクトルを描き直し、下はオリジナルのまま",
"The file split into stems: four, six, eight, or the voice and the rest": "ファイルをステムに分けます：4、6、8、またはボーカルと残り",
"The stems on lanes: levels, versions, buses and automation, then a mix": "トラック上のステム：レベル、バージョン、バス、オートメーション、そしてミックス",
"The Digital Gateway: tape, console and tube in numbers, on a file or a mix": "デジタルゲートウェイ：テープ、コンソール、真空管を数値で、ファイルやミックスに",
"The Debunker: a file or a set of stems balanced, compressed, toned and brought to a loudness": "Debunker：ファイルやステムのセットを整え、圧縮し、音色を整え、ラウドネスに合わせます",
