"{0} is the gateway's own card, which opens once: choose another output for the monitor": "{0} はゲートウェイ自身のカードで、一度しか開けません。モニターには別の出力を選んでください",   // HERESY 1568
"Not kept: {0}": "保存できません：{0}",
"Who may open this studio?": "このスタジオを開けるのは誰？",
"The studio listens on port {0} of every network this computer is on. Whoever opens its page can do everything you can: make and delete songs, read your lyrics, run your graphics cards, fetch models with your keys.": "スタジオは、このコンピューターがつながっているすべてのネットワークのポート {0} で待ち受けます。そのページを開いた人は、あなたにできることをすべてできます：曲の作成と削除、歌詞の閲覧、グラフィックカードの使用、あなたのキーでのモデルのダウンロード。",
"At home behind your router, private networks are what you want: your laptop and phone reach the studio, the internet does not.": "自宅でルーターの内側なら、プライベートネットワークが望ましい選択です。ノートパソコンや電話はスタジオに届き、インターネットは届きません。",
"On a public Wi-Fi (a café, a hotel, a train) or on a laptop without a firewall, everyone on that network counts as a private network too: choose This computer only, or list your own networks.": "公共 Wi-Fi（カフェ、ホテル、列車）や、ファイアウォールのないノートパソコンでは、そのネットワークにいる全員がプライベートネットワークとみなされます。「このコンピューターだけ」を選ぶか、自分のネットワークを挙げてください。",
"Engine → Security changes it any time. The internet at large is never let in, unless the studio is started with RUACH_ALLOW_PUBLIC=1.": "エンジン → セキュリティでいつでも変えられます。RUACH_ALLOW_PUBLIC=1 で起動しない限り、インターネット全体が入ることはありません。",
