"Set it": "適用",
"Keep the setup as it is now under this name": "今のセットアップをこの名前で上書き保存",
"Delete the profile «{0}»?": "プロファイル「{0}」を削除しますか？",
"Profile «{0}» kept": "プロファイル「{0}」を保存しました",
"Profile «{0}» set: {1} settings changed": "プロファイル「{0}」を適用：{1} 件の設定を変更",
