"The profiles could not be kept: {0}": "プロファイルを保存できませんでした：{0}",
"Clone": "複製",
"Delete the clone": "複製を削除",
"A second node of this step with its own settings, beside it: its window holds them, and a run from there runs with them": "このステップの2つ目のノード（独自の設定付き）を隣に：そのウィンドウが設定を保持し、そこからの実行はその設定で動きます",
"its own settings": "独自の設定",
"{0} cloned: its window holds its own settings": "{0} を複製しました：そのウィンドウが独自の設定を保持します",
"Delete the clone «{0}»? Its settings go with it.": "複製「{0}」を削除しますか？その設定も一緒に消えます。",
"Eight clones of one step are enough": "1つのステップの複製は8つまでです",
"Every Generate keeps this title's style, lyrics and score apart from the takes: its versions, a diff of two, one back into the form": "Generate のたびに、このタイトルのスタイル・歌詞・スコアをテイクとは別に保存します：そのバージョン、2つの差分、1つをフォームに戻す",
"Every Generate's words, kept under their title apart from the takes: a take deleted never takes them along": "各 Generate の言葉を、テイクとは別にタイトルごとに保存：テイクを削除しても言葉は消えません",
"Creator's versions": "クリエイターのバージョン",
"The Creator's version was not kept: {0}": "クリエイターのバージョンを保存できませんでした：{0}",
"The Creator's versions did not come: {0}": "クリエイターのバージョンを取得できませんでした：{0}",
"too long to compare line by line": "長すぎて行ごとに比較できません",
"the same": "同じ",
"unchanged lines: {0}": "変更のない行：{0}",
"a click picks a version; Ctrl or Shift and a click, a second: their difference": "クリックでバージョンを選択；Ctrl か Shift を押しながらクリックで2つ目：その差分",
"versions: {0}": "バージョン：{0}",
