"Close (Esc): back to the box, the match selected": "閉じる (Esc)：入力欄に戻り、見つかった箇所を選択",
"Back to the last quarter-minute mark (0:15, 0:30…). The ← key: to the last 5 s mark": "直前の15秒区切り（0:15、0:30…）へ戻る。← キー：直前の5秒区切りへ",
"Same as the text": "本文と同じ",
"Up to three parts of the frame, each with words of its own: at every step the painter is asked once more for each region, with the prompt and the region's words, and the answers are blended by soft-edged boxes (Latent Couple's way). Each region costs a whole pass more a step. Qwen-Image 2512": "フレームを最大3つの領域に分け、それぞれに独自の言葉を：各ステップで領域ごとにプロンプトと領域の言葉で画家にもう一度問い、その答えを柔らかい縁のボックスで混ぜ合わせます（Latent Couple 方式）。領域1つにつき、1ステップあたり丸ごと1パス余分にかかります。Qwen-Image 2512",
"The score written in {0} (it came as {1}): the same notes, spelled as the engine sings them": "スコアを {0} で書き直しました（届いたのは {1}）：同じ音を、エンジンが歌う綴りで",
"Export all: every document of the Writer, with its versions, the takes made from it and its trash, and the Creator's versions of every title, in one file (a backup)": "すべてをエクスポート：ライターの各ドキュメント（そのバージョン、そこから作ったテイク、ゴミ箱）と、各タイトルのクリエイターのバージョンを1つのファイルに（バックアップ）",
"Import a Writer backup: what is missing here comes in; the same is left alone; a document that differs from its namesake here comes in beside it as a copy; a title of the Creator's versions here gains the versions it lacks. Nothing here is written over": "ライターのバックアップをインポート：ここにないものは入り、同じものはそのまま、ここの同名と異なるドキュメントはコピーとして隣に入り、クリエイターのバージョンのタイトルには足りないバージョンが加わります。ここでは何も上書きされません",
"Writer backup: {0} documents and {1} in the trash, the Creator's versions of {2} titles, into {3}": "ライターのバックアップ：ドキュメント {0} 件、ゴミ箱 {1} 件、クリエイターのバージョン {2} タイトル分を {3} へ",
"the Creator's versions: {0} new, {1} titles new": "クリエイターのバージョン：新規 {0} 件、新しいタイトル {1} 件",
"Refiner Room": "仕上げ師のルーム",
"How the Refiner room opens: its steps as a list, or its nodes on a canvas. The List and Canvas button in the room's head switches at any time.": "仕上げ師のルームの開き方：ステップをリストで、またはノードをキャンバスで。ルーム上部の「リスト / キャンバス」ボタンでいつでも切り替えられます。",
"The Refiner is a canvas of nodes: every step a node, wired the way the work flows and numbered by it; a click or its number's key (1…9, 0) opens one.": "仕上げ師はノードのキャンバスです：各ステップがノードで、作業の流れどおりにつながり、その順に番号が付きます。クリックするか番号のキー（1…9、0）で開きます。",
"The Refiner opens": "仕上げ師の開き方",
"As it was left": "前回のまま",
"The view the room had when you last left it.": "最後にルームを離れたときの表示。",
"Always the list": "常にリスト",
"The steps one under another, as the Refiner began.": "ステップを縦に並べた、仕上げ師の最初の形。",
"Always the canvas": "常にキャンバス",
"The nodes and their wires; a click opens one; nothing to scroll at 1080p.": "ノードとそのワイヤー。クリックで開きます。1080p でもスクロール不要。",
"About models and LoRAs": "モデルと LoRA について",
"About folders": "フォルダについて",
"Into this take's trash, from where it comes back": "このテイクのゴミ箱へ（そこから戻せます）",
"deleted with {0}": "{0} と一緒に削除",
"Empty the trash": "ゴミ箱を空にする",
"Delete the branch «{0}»?": "ブランチ「{0}」を削除しますか？",
"It goes into this take's trash, from where it comes back.": "このテイクのゴミ箱に入り、そこから戻せます。",
"Into the trash: {0}": "ゴミ箱へ：{0}",
"Branches were made from «{0}»: {1}.": "「{0}」から作られたブランチ：{1}。",
"They go into the trash with it, and come back from it each on its own.": "一緒にゴミ箱に入り、それぞれ個別に戻せます。",
"Delete them too": "それらも削除",
"Back on the tree": "ツリーに戻しました",
"Empty this take's trash?": "このテイクのゴミ箱を空にしますか？",
"Branches gone for good: {0}. This cannot be undone.": "完全に削除されるブランチ：{0}。元に戻せません。",
"The take's trash emptied: {0}": "テイクのゴミ箱を空にしました：{0}",
"At a tempo": "テンポに合わせて",
"Attack": "アタック",
"Band": "バンド",
"Bell": "ベル",
"Clear the loudness, the true peak and every peak held": "ラウドネス、トゥルーピーク、保持したピークをすべてクリア",
"Comp": "コンプ",
"Compressor": "コンプレッサー",
"Console": "コンソール",
"Devices": "デバイス",
"Double-click to add a band there; drag a band's point (Shift finer); the wheel over it sets its width; a right-click takes it away. Behind the curve: the strip's own sound as it plays": "ダブルクリックでそこにバンドを追加。バンドの点をドラッグ（Shift で細かく）、その上でホイールを回すと幅、右クリックで削除。カーブの後ろはトラック自身の音（再生中）",
"Each echo darker than the one before, above this": "エコーごとに前より暗く、この周波数より上で",
"Everything set here is heard as it is set and mixed on Forge as it is heard: the same EQ, compressor, pan, room and delay. Drag along a wave to silence a stretch, right-click it to give it back, click to play from there.": "ここで設定したものは設定したとおりにすぐ聞こえ、聞こえるとおりに Forge でミックスされます。同じ EQ、コンプレッサー、パン、ルーム、ディレイ。波形に沿ってドラッグすると区間を無音に、右クリックで戻し、クリックでそこから再生します。",
"Feedback": "フィードバック",
"Freq": "周波数",
"Gain": "ゲイン",
