"How fast it lets go": "どれだけ速く離すか",
"How fast it takes hold": "どれだけ速くつかむか",
"How much it holds back above the threshold": "スレッショルドより上をどれだけ抑えるか",
"How much of each echo comes back as the next": "各エコーのどれだけが次として戻るか",
"How softly it bends into the ratio": "レシオへどれだけやわらかく曲がるか",
"In and out: the line bends at the threshold by the ratio, softly over the knee": "入力と出力：線はスレッショルドでレシオどおりに折れ、ニーの範囲でやわらかく",
"Input": "入力",
"Its decay to −60 dB": "−60 dB までの減衰",
"Its devices: input, EQ, compressor, output": "そのデバイス：入力、EQ、コンプレッサー、出力",
"Knee": "ニー",
"Knobs: drag up and down, Shift finer, a double-click back to where it was": "ノブ：上下にドラッグ、Shift で細かく、ダブルクリックで元に戻す",
"Level": "レベル",
"Loudness by BS.1770 as it plays: momentary (0.4 s), short-term (3 s), integrated since play was pressed; the true peak 4× interpolated; the sides' correlation (+1 mono, 0 wide, −1 out of phase)": "再生中の BS.1770 ラウドネス：モーメンタリー（0.4 秒）、ショートターム（3 秒）、▶ を押してからのインテグレーテッド。トゥルーピークは 4 倍補間。左右の相関（+1 モノ、0 ワイド、−1 逆相）",
"Low cut": "ローカット",
"Low shelf": "ローシェルフ",
