"Master": "マスター",
"Mix it on Forge as it is heard here: a branch of the tree, its loudness measured": "ここで聞こえるとおりに Forge でミックス：ツリーの枝として、ラウドネスを測定",
"Mix with its stems: every strip as it sounds in the mix, and each return, its own file beside the mix": "ステム付きでミックス：ミックス内で鳴っているとおりの各トラックと各リターンを、ミックスの横に別ファイルで",
"Mute the return": "リターンをミュート",
"No bands yet: double-click the curve where it should change, or + Band": "まだバンドがありません。変えたい所でカーブをダブルクリックするか、＋バンド",
"Notch": "ノッチ",
"On and off: heard at once": "オン・オフ：すぐ聞こえます",
"Pan": "パン",
"Pan: the strip between the sides (the browser's stereo panner, the render's law)": "パン：左右の間のトラック（ブラウザーのステレオパンナー、レンダーと同じ法則）",
"Polarity: the strip upside down": "極性：トラックを上下反転",
