"The crossfade between the playlist's takes, 0 to 4 s; Previous and Next change at once": "プレイリストのテイク間のクロスフェード、0〜4 秒。前へ・次へはすぐに切り替わります",
"The playlist's crossfade": "プレイリストのクロスフェード",
// HERESY 1738: the Refiner's Mono Maker, Peak glue and True-peak ceiling
"Mono Maker": "低域モノ化",
"Peak glue": "ピークグルー",
"True-peak ceiling": "トゥルーピーク上限",
"the lows in the middle": "低域を中央へ",
"the loud moments shaved, the loudness kept": "大きな瞬間を削り、音量はそのまま",
"the last step: no peak over the ceiling": "最後のステップ：上限を超えるピークなし",
"Below the frequency the side (L − R) is taken out, as much as asked; above it nothing changes. The side is high-passed with a zero-phase filter and the mid left as it is, so the bass and the kick sit in the centre and the stereo stays where it lives. Shaumarov's first tool on the instrument bus and the master.": "周波数より下のサイド（L − R）を指定した分だけ取り除き、上は何も変えません。サイドは位相のずれないフィルターを通り、ミッドはそのまま。ベースとキックは中央に座り、ステレオは本来の場所に残ります。Shaumarov が楽器バスとマスターで最初に使う道具です。",
"A gentle compressor before anything else, as Shaumarov prepares a voice or a mix: only the loud moments lose the dB asked (its threshold found for that), the sharpest transients pass, and the file comes back as loud as it came. No ceiling here: put the True-peak ceiling at the end of the way.": "何よりも先に置くやさしいコンプレッサー。Shaumarov が声やミックスを下ごしらえするように、大きな瞬間だけが指定の dB を失い（そのためのスレッショルドを探します）、鋭いトランジェントは通り、ファイルは元の音量で戻ります。ここに上限はありません：トゥルーピーク上限を道の最後に置いてください。",
"An oversampled lookahead limiter, its ceiling checked by a true-peak meter. «as it came» only catches the overs at the file's own loudness; a loudness target drives into it (at most 6 dB of limiting). Shaumarov ends the master at about −0.5 dBTP.": "オーバーサンプリングと先読みのリミッター。上限はトゥルーピークメーターで確かめます。「入ったまま」はファイル自身の音量で超過だけを捕まえ、ラウドネス目標はそこへ押し込みます（リミッティングは最大 6 dB）。Shaumarov はマスターを約 −0.5 dBTP で締めます。",
"Below, Hz": "以下、Hz",
"Shave, dB": "削る量、dB",
"Attack, ms": "アタック、ms",
"Release, ms": "リリース、ms",
"Ceiling, dBTP": "上限、dBTP",
"The frequency under which the stereo goes to the middle": "これより下でステレオが中央に集まる周波数",
"How much of the side under it goes: all of it, or a part": "その下のサイドをどれだけ取るか：全部か一部か",
"How much the loud moments lose": "大きな瞬間が失う量",
"How fast it takes hold: slower lets more of the transients through": "掴む速さ：遅いほどトランジェントを多く通す",
"No peak over it, between the samples too": "その上にピークなし、サンプル間でも",
"The file's own loudness, or a target to drive to": "ファイル自身の音量か、向かう目標",
"Mono below {#0} Hz": "{0} Hz 以下をモノ",
"Mono below {#0} Hz, {#1} %": "{0} Hz 以下をモノ、{1} %",
"Peak glue, {#0} dB": "ピークグルー、{0} dB",
"Ceiling {#0} dBTP": "上限 {0} dBTP",
"Ceiling {#0} dBTP, {#1} LUFS": "上限 {0} dBTP、{1} LUFS",
