"Backing Vocals (tamed)": "Backing Vocals（テイム済み）",
"Vocals (tamed)": "Vocals（テイム済み）",
"Lead Vocal (attack and body)": "Lead Vocal（アタックとボディ）",
"Backing Vocals (attack and body)": "Backing Vocals（アタックとボディ）",
"Vocals (attack and body)": "Vocals（アタックとボディ）",
"Bass (under the kick)": "Bass（キックの下）",
"Details up, {#0} %": "ディテールを持ち上げる、{0}%",
"Keep the voice's own": "声本来の色合いを保つ",
"Every bulge": "すべての山",
"Keep the voice's own: only what rises over its usual bulges at that moment (a singer's formant is its presence and stays). Every bulge: its colour lowered too": "声本来の色合いを保つ：その瞬間にいつもの山を超えて盛り上がる部分だけ（歌い手のフォルマントは声の存在感なので残ります）。すべての山：色合いも下げます",
// HERESY 1752: the Trainer's learning-rate fade
"LR fade, epochs": "LR の減衰、エポック",
"Over the run's last this many epochs the learning rate goes down in a straight line, to the share below at its last step: the usual way to end a run, the last saves settling instead of stepping on as hard. It follows the run's length, so a run gone on longer fades at its new end. 0: none, the rate the same to the end.": "ラン最後のこのエポック数のあいだ、学習率を直線的に下げ、最後のステップで下の割合にします。ランを終えるいつものやり方で、最後のセーブが同じ強さで踏み出す代わりに落ち着きます。ランの長さに合わせるので、延長したランは新しい終わりで減衰します。0：なし、最後まで同じ学習率。",
"LR at the end, %": "最後の LR、%",
"What is left of the learning rate at the run's last step, in per cent of it: 0 fades it out": "ラン最後のステップで残る学習率の割合（%）：0 で完全に消えます",
"The learning rate fades over the last {0} epochs to {1} % of itself.": "学習率は最後の {0} エポックで自身の {1} % まで減衰します。",
"fade": "減衰",
"the last {0} epochs to {1} %": "最後の {0} エポックで {1} %",
// HERESY 1753–1756: the DAW gone over: the solo light, the reference, the song's fade
"Solo is on: {0} of {1} lanes heard, and Mix makes only them. A click (or Alt+click on any S) lets every lane be heard again": "ソロがオン：{1} トラック中 {0} トラックだけが聞こえ、ミックスもそれだけを作ります。クリック（または任意の S を Alt+クリック）ですべてのトラックがまた聞こえます",
"Ref": "原音",
"The sound as it came, the one the stems were split from (a neutral mix gives it back), heard in place of the mix and as loud as it over what has played: so the compare is of the sound, not of the level. The button says by how much it is raised or lowered; R does the same; Mono and Dim hear it too": "届いたままの音（ステムを分けた元の音。ニュートラルなミックスはこれに戻ります）を、ミックスの代わりに、再生した区間でミックスと同じラウドネスで聴きます。こうして比べるのは音であってレベルではありません。ボタンには上げ下げした量が出ます。R でも同じ、モノとディムもこの音にかかります",
"The source's loudness did not come from the lab: the reference plays as it is, not matched": "元の音のラウドネスがラボから届きませんでした：リファレンスは合わせずそのまま鳴ります",
"Fade": "フェード",
"Fade in": "フェードイン",
"The song comes up from −60 dB over this many seconds; 0: no fade-in": "曲がこの秒数で −60 dB から立ち上がります。0：フェードインなし",
"Fade out": "フェードアウト",
"The song goes down to −60 dB over this many seconds before its end; 0: no fade-out": "曲が終わりまでのこの秒数で −60 dB まで下がります。0：フェードアウトなし",
"Ends at": "終わり",
"the song's end": "曲の終わり",
"The song ends at the playhead: silent from there, the fade-out before it": "曲は再生位置で終わります：そこから無音、その前にフェードアウト",
"At the playhead": "再生位置で",
"At the song's end": "曲の終わりに",
"Linear in dB from −60 dB and down to it, after the master's fader, as the mix on Forge has it; drawn dark over the lanes": "−60 dB から、また −60 dB まで dB で直線的に。マスターのフェーダーの後、Forge のミックスと同じ。トラックの上に暗く描かれます",
"Space plays and stops; Home to the start (the loop's, when it is on); L the loop; M and S the lane picked by a click on its name; ↑ ↓ another lane; + − 0 the zoom; [ ] the section before and after; Ctrl+Z, Ctrl+Shift+Z undo and redo; R the sound as it came, as loud as the mix; Alt+click on an S: every solo off": "Space：再生と停止、Home：先頭へ（ループがオンならその先頭）、L：ループ、M と S：名前クリックで選んだトラック、↑ ↓：別のトラック、+ − 0：ズーム、[ ]：前と次のセクション、Ctrl+Z・Ctrl+Shift+Z：元に戻す・やり直し、R：届いたままの音（ミックスと同じラウドネス）、S を Alt+クリック：ソロをすべて解除",
