"A stretch of the take sung anew with adapters of its own: drag along the wave to lay the window, drag its edges to move them. Over the ramps before and after it the take's own adapters give way to the window's and back; the rest of the take stays as it is.": "テイクの一区間を独自のアダプターで歌い直します。波形をドラッグしてウィンドウを置き、端をドラッグして動かします。前後のランプでテイクのアダプターがウィンドウのアダプターに入れ替わり、また戻ります。テイクの残りはそのままです。",
"The take's wave: drag to lay the window": "テイクの波形：ドラッグしてウィンドウを置く",
