// HERESY 1759: parallel compression
"Parallel compression: the compressed sound blended with the dry one; 100 % the compressor alone": "パラレル・コンプレッション：圧縮した音を素の音と混ぜます。100 % でコンプレッサーのみ",
"Parallel": "パラレル",
// HERESY 1760: a strip's gate
