"Below it the gate closes, by its ratio": "これを下回るとゲートが比率に従って閉じます",
"How much it lowers what is under the threshold: 4:1 takes 10 dB under it down 40": "しきい値より下をどれだけ下げるか：4:1 なら 10 dB 下の音を 40 dB 下げます",
"The most it lowers anything: the floor the bleed is left at": "下げる量の最大値：かぶりが残る床",
"How fast it opens when the sound comes back": "音が戻ったときに開く速さ",
"How fast it closes after the sound: longer, the tails kept": "音のあと閉じる速さ：長いほど余韻が残ります",
"The gate: what it takes away between the phrases as it plays": "ゲート：再生中にフレーズの間で取り除く量",
"The gate's reduction as it plays": "再生中のゲートの減衰量",
"It listens to the strip itself, after its EQ: below the threshold the strip goes down by the ratio, never more than the range, so the bleed between the phrases falls away": "トラック自身を EQ の後で聴きます。しきい値を下回るとトラックは比率に従って下がり、レンジより深くは下がらないので、フレーズ間のかぶりが消えます",
// HERESY 1762: the returns' pre-delay and cuts
