"The room comes in this much after the sound, on top of its own: the word clear before its room": "ルームが音のこれだけ後に、それ自身の遅れに加えて入ります：ルームが来る前に言葉がはっきり聞こえます",
"Below this the room is cut: no mud under the voice; Off at 20 Hz": "これより下でルームをカット：声の下に濁りなし。20 Hz でオフ",
"Above this the room is cut: a darker room, the sibilants out of it; Off at 20 kHz": "これより上でルームをカット：暗めのルームで、歯擦音がルームから消えます。20 kHz でオフ",
"Below this the echoes are cut, all of them alike: no bass in them; Off at 20 Hz": "これより下でエコーをカット、すべて同じに：低音なし。20 Hz でオフ",
