// HERESY 1763: the master's loudness range and PLR
"The loudness range since play, by EBU Tech 3342: how far the song's short-term loudness moves, its quietest 10 % and its loudest 5 % left out; the mix on Forge says its own": "再生開始からのラウドネスレンジ（EBU Tech 3342）：曲の短期ラウドネスがどれだけ動くか。最も静かな 10 % と最も大きい 5 % は除きます。Forge のミックスは自分の値を示します",
"Peak to loudness: the true peak over the integrated loudness since play; the smaller, the more squashed the song": "ピーク対ラウドネス：再生開始からの統合ラウドネスに対するトゥルーピーク。小さいほど曲は潰れています",
