"A run started elsewhere stopped on a broken score: {0}. Nothing was sung, nothing here changed": "別の場所で始まった実行が壊れた楽譜で止まりました: {0}。何も歌われず、ここでは何も変わっていません",
// HERESY 1768: the decode ladder in the Creator
"Sound decode": "音のデコード",
"Whole song · standard": "曲全体 · 標準",
"Ladder · experimental": "ラダー · 実験的",
"Experimental: what comes out differs from the standard decode. How the sound half turns the music codes into sound. Whole song, the standard (and the only way everywhere else in the Studio): one solve over the whole song, stable and predictable. Ladder: the song in even pieces of about 20 s, each solved hearing 2 s of the music past both its edges, the neighbours crossfaded over the 2 s round each joint (the best of the probes by Viktor's ear, 24.10.2026). On the same codes and seeds it comes out close to the whole-song decode, not the same, and further from it on a fine-tuned checkpoint; for now it takes the same time. A song under 20 s is one piece. Only the Creator's runs and their «Also render with» go this way; a section or a window sung anew, a new sound, a trim, an end or a fade-in in the player decode the standard way.": "実験的：出てくる音は標準のデコードと異なります。音の半分が音楽のコードを音に変える方法です。曲全体（標準。スタジオのほかの場所はすべてこの方法）：曲全体を一度に解き、安定して予測できます。ラダー：曲を約 20 秒の等しい区切りに分け、それぞれ両端の先 2 秒の音楽を聞きながら解き、各つなぎ目の前後 2 秒で隣同士をクロスフェードします（ヴィクトルの耳でプローブの中の最良、2026年10月24日）。同じコードとシードでは曲全体のデコードに近いものの同じではなく、ファインチューンしたチェックポイントではさらに離れます。今のところかかる時間は同じです。20 秒未満の曲は一つの区切りです。この方法を使うのはクリエイターの実行とその「ほかのソルバーでも」だけです。歌い直したセクションやウィンドウ、新しい音、トリム、エンド、プレーヤーでのフェードインは標準の方法でデコードされます。",
